<?php
declare(strict_types=1);
require_once __DIR__ . '/../core/helpers.php';require_once __DIR__ . '/../core/auth.php';require_once __DIR__ . '/../core/storage.php';require_once __DIR__ . '/../core/csrf.php';
start_secure_session(); ensure_data_files(); require_admin();
$playlist=read_json(PLAYLIST_FILE); $id=$_GET['id']??''; $idx=null; foreach($playlist as $k=>$t){if(($t['id']??'')===$id){$idx=$k;break;}} if($idx===null) exit('Brano non trovato');
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_validate(); backup_playlist(); foreach(['order','title','artist','album','year','description'] as $f){$playlist[$idx][$f]=($f==='order')?(int)$_POST[$f]:trim($_POST[$f]??'');}
$playlist[$idx]['rights']=['author'=>trim($_POST['rights_author']??''),'license'=>trim($_POST['rights_license']??''),'origin'=>trim($_POST['rights_origin']??''),'ai_assisted'=>!empty($_POST['rights_ai_assisted']),'notes'=>trim($_POST['rights_notes']??'')]; atomic_write_json(PLAYLIST_FILE,$playlist); redirect('/admin/dashboard.php');}
$t=$playlist[$idx]; app_header('Modifica brano'); echo '<main class="container"><h1>Modifica brano</h1><form method="post">'.csrf_input().'<label>Titolo<input name="title" value="'.e($t['title']).'"></label><label>Artista<input name="artist" value="'.e($t['artist']).'"></label><label>Album<input name="album" value="'.e($t['album']).'"></label><label>Anno<input name="year" value="'.e($t['year']).'"></label><label>Ordine<input name="order" type="number" value="'.(int)$t['order'].'"></label><label>Descrizione<textarea name="description">'.e($t['description']).'</textarea></label><h2>Diritti</h2><label>Autore<input name="rights_author" value="'.e($t['rights']['author']??'').'"></label><label>Licenza<input name="rights_license" value="'.e($t['rights']['license']??'').'"></label><label>Origine<input name="rights_origin" value="'.e($t['rights']['origin']??'').'"></label><label><input type="checkbox" name="rights_ai_assisted" '.(!empty($t['rights']['ai_assisted'])?'checked':'').'> AI assisted</label><label>Note<textarea name="rights_notes">'.e($t['rights']['notes']??'').'</textarea></label><button>Aggiorna</button></form></main>'; app_footer();
